<script setup>
import {s,canAdmin,isSuper,run,previewMembers,importMembers,number} from './store';
</script><template><section class="card stack"><div class="toolbar"><div><h3>Người được quyền chỉnh sửa</h3><p class="muted">Mọi tài khoản MISA đăng nhập đều có quyền xem sự kiện. Danh sách này cấp quyền chỉnh sửa riêng cho sự kiện hiện tại.</p></div><MButton variant="primary" v-if="canAdmin" @click="s.dialog='member'">Thêm thành viên</MButton></div><template v-if="canAdmin"><MUpload accept=".xlsx" :multiple="false" :max-size-m-b="10" :disabled="s.busy" label="Import thành viên Excel — Họ và tên, Email" @select-files="run(()=>previewMembers($event))" @oversized="s.error='File tối đa 10 MB.'" /><p class="muted">Import cấp Editor. Không gửi link mời. Tài khoản mới dùng mật khẩu mặc định đã bàn giao và phải đổi ở lần đăng nhập đầu. Tài khoản đã tồn tại giữ nguyên mật khẩu.</p><div v-if="s.memberPreview" class="stack"><p>{{number(s.memberPreview.rows.length)}} thành viên hợp lệ / {{number(s.memberPreview.total)}} dòng.</p><p v-for="e in s.memberPreview.errors" :key="e.row" class="error">Dòng {{e.row}}: {{e.message}}</p><div class="mobile-list"><article v-for="m in s.memberPreview.rows" :key="m.email">{{m.name}} · {{m.email}} · Editor</article></div><div class="row justify-end"><MButton variant="secondary" @click="s.memberPreview=null">Hủy</MButton><MButton variant="primary" :disabled="!!s.memberPreview.errors.length||!s.memberPreview.rows.length" :loading="s.busy" @click="run(importMembers)">Xác nhận import</MButton></div></div></template></section></template>
